target.css:
:root {
  --paper: #fffaf0;
  --ink: #26313b;
  --line: #d8cdbb;
  --coral: #eb765f;
  --ochre: #e4ad48;
  --blue: #5b98bd;
}

.mix-card {
  width: 460px;
  box-sizing: border-box;
  padding: 18px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
  color: var(--ink);
}

.mix-card header {
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.mix-card h1,
.mix-card p {
  margin: 0;
}

.eyebrow {
  margin-bottom: 5px !important;
  color: var(--coral);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

.mix-card h1 {
  font-size: 22px;
  line-height: 1.1;
}

.mix-card header p:last-child {
  margin-top: 5px;
  font-size: 13px;
}

.swatches {
  display: flex;
  gap: 8px;
  padding: 14px 0;
}

.swatch {
  flex: 1;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 12px;
}

.swatch span {
  display: block;
  width: 23px;
  margin-bottom: 6px;
  padding: 3px 0;
  border-radius: 5px;
  background: var(--coral);
  color: var(--paper);
  font-size: 12px;
  font-weight: 800;
  text-align: center;
}

.swatch:nth-child(2) span {
  background: var(--ochre);
}

.swatch:nth-child(3) span {
  background: var(--blue);
}

.swatch strong {
  font-size: 12px;
}

.mix-card footer {
  padding-top: 10px;
  border-top: 1px solid var(--line);
  font-size: 12px;
  font-weight: 600;
}

.note-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 5px;
  border-radius: 50%;
  background: var(--blue);
}

